import{_ as s,r,o as c,c as a,e as t,a as d,s as l}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Directory Structure - October CMS - 4.x","titleTemplate":false,"description":"Find out the purpose of each directory in the October CMS root folder","frontmatter":{"subtitle":"Find out the purpose of each directory in the October CMS root folder"},"headers":[{"level":2,"title":"Root Directory","slug":"root-directory","link":"#root-directory","children":[{"level":3,"title":"App Directory","slug":"app-directory","link":"#app-directory","children":[]},{"level":3,"title":"Bootstrap Directory","slug":"bootstrap-directory","link":"#bootstrap-directory","children":[]},{"level":3,"title":"Config Directory","slug":"config-directory","link":"#config-directory","children":[]},{"level":3,"title":"Plugins Directory","slug":"plugins-directory","link":"#plugins-directory","children":[]},{"level":3,"title":"Storage Directory","slug":"storage-directory","link":"#storage-directory","children":[]},{"level":3,"title":"Modules Directory","slug":"modules-directory","link":"#modules-directory","children":[]},{"level":3,"title":"Themes Directory","slug":"themes-directory","link":"#themes-directory","children":[]},{"level":3,"title":"Vendor Directory","slug":"vendor-directory","link":"#vendor-directory","children":[]}]},{"level":2,"title":"App Directory","slug":"app-directory-1","link":"#app-directory-1","children":[{"level":3,"title":"Assets Directory","slug":"assets-directory","link":"#assets-directory","children":[]},{"level":3,"title":"Blueprints Directory","slug":"blueprints-directory","link":"#blueprints-directory","children":[]},{"level":3,"title":"Others Directories","slug":"others-directories","link":"#others-directories","children":[]}]}],"relativePath":"4.x/setup/directory-structure.md","filePath":"4.x/setup/directory-structure.md"}'),n={name:"4.x/setup/directory-structure.md"};function h(p,e,u,y,f,m){const o=r("pre-heading"),i=r("post-heading");return c(),a("div",null,[t(o),e[0]||(e[0]=d("h1",null,"Directory Structure",-1)),t(i),e[1]||(e[1]=l('<p>October CMS uses a modular structure where most programming features are found in either the modules or plugins directory.</p><h2 id="root-directory"><a href="#root-directory" class="header-anchor">#</a> Root Directory</h2><h3 id="app-directory"><a href="#app-directory" class="header-anchor">#</a> App Directory</h3><p>The <code>app</code> directory contains application specific code. The contents of this directory are explored in more detail after this section. In summary, this area contains business logic that doesn&#39;t belong in traditional plugins. Most of the plugin features are available in this directory.</p><h3 id="bootstrap-directory"><a href="#bootstrap-directory" class="header-anchor">#</a> Bootstrap Directory</h3><p>The <code>bootstrap</code> directory contains the app.php bootstrap script that loads the Laravel framework. The directory also contains the custom PHP class autoloader. Typically, files in this directory should not be modified.</p><h3 id="config-directory"><a href="#config-directory" class="header-anchor">#</a> Config Directory</h3><p>The <code>config</code> directory contains all the application configuration files. Each file controls how the application functions. Configuration files can be changed according to your application requirements. System updates do not modify the configuration files.</p><h3 id="plugins-directory"><a href="#plugins-directory" class="header-anchor">#</a> Plugins Directory</h3><p>The <code>plugins</code> directory packages that extend the core functionality of October CMS. Plugins can modify the platform by introducing new features. By default, the system loads all plugins found in the filesystem. Specific plugins can be disabled using the <code>system.disable_plugins</code> configuration parameter.</p><h3 id="storage-directory"><a href="#storage-directory" class="header-anchor">#</a> Storage Directory</h3><p>The <code>storage</code> directory contains log files, cache files, sessions and other files generated by October CMS. It includes several subdirectories:</p><ul><li><code>app</code> - contains application-specific storage files, such as media files, file uploads and automatically generated resources, e.g. resized files and combined asset files.</li><li><code>framework</code> - used by the Laravel framework to store its generated files and caches.</li><li><code>cms</code> - used by the October CMS platform to store its generated files and caches.</li><li><code>logs</code> - contains the application&#39;s log files.</li><li><code>temp</code> - used to store temporary application files.</li></ul><h3 id="modules-directory"><a href="#modules-directory" class="header-anchor">#</a> Modules Directory</h3><p>The <code>modules</code> directory contains the core packages of October CMS, providing core functionality that is common across the system. By default, modules are loaded automatically based on their presence in the file system. However, it is possible to specify which modules to load with the <code>system.load_modules</code> configuration parameter. The <code>system</code> module must be loaded at a minimum for the application to operate.</p><ul><li><code>system</code> - defines the core functionality of October CMS and is a required module.</li><li><code>cms</code> - introduces functionality for rendering the frontend website theme. It is responsible for routing requests to pages, rendering pages and handling AJAX requests.</li><li><code>backend</code> - responsible for displaying the backend panel pages.</li><li><code>editor</code> - introduces a user interface for editing CMS templates in the backend panel.</li><li><code>media</code> - introduces a media file management user interface in the backend panel. It allows back-end users to upload media files like images or video files and include them in other places, for example, blog posts.</li><li><code>tailor</code> - introduces the October CMS Tailor features.</li></ul><h3 id="themes-directory"><a href="#themes-directory" class="header-anchor">#</a> Themes Directory</h3><p>The <code>themes</code> directory contains subdirectories for front-end website CMS themes. CMS themes include template files for the website pages, layouts, partials, assets, and other files. The active theme is set using the <code>cms.active_theme</code> configuration parameter and can be overridden from the backend panel settings page.</p><h3 id="vendor-directory"><a href="#vendor-directory" class="header-anchor">#</a> Vendor Directory</h3><p>The <code>vendor</code> directory contains packages that are included via Composer. Some plugins can include the vendor directory as well. The system vendor directory takes priority over plugin-specific vendor directories.</p><h2 id="app-directory-1"><a href="#app-directory-1" class="header-anchor">#</a> App Directory</h2><p>The <code>app</code> directory contains application-specific files, including contents, assets and business logic that doesn&#39;t belong in a <a href="./../extend/system/plugins.html">traditional plugin</a>. It includes a Service Provider file that is loaded by the default configuration.</p><h3 id="assets-directory"><a href="#assets-directory" class="header-anchor">#</a> Assets Directory</h3><p>The <code>app/assets</code> directory contains asset files, such as JavaScript, CSS and image files. This directory should be publically accessible to the website.</p><h3 id="blueprints-directory"><a href="#blueprints-directory" class="header-anchor">#</a> Blueprints Directory</h3><p>The <code>app/blueprints</code> directory contains <a href="./../cms/tailor/introduction.html">content blueprint</a> files used by Tailor.</p><h3 id="others-directories"><a href="#others-directories" class="header-anchor">#</a> Others Directories</h3><p>You may create any directory in here, just like a plugin, such as <code>models</code> or <code>controllers</code>. These will be autoloaded in the <code>App</code> namespace. For example, the file <strong>app/models/Customer.php</strong> will be available in PHP as <code>App\\Models\\Customer</code>.</p>',28))])}const v=s(n,[["render",h]]);export{b as __pageData,v as default};
